changes.content:
networks:
  1panel-network:
    external: true
services:
  anirss:
    container_name: ${CONTAINER_NAME}
    deploy:
      resources:
        limits:
          cpus: ${CPUS}
          memory: ${MEMORY_LIMIT}
    environment:
    - PUID=99
    - PGID=100
    - UMASK=${UMASK}
    - TZ=${TZ}
    - SERVER_PORT=${SERVER_PORT}
    - CONFIG=${CONFIG}
    - JAVA_OPTS=${JAVA_OPTS}
    - SWAGGER_ENABLED=${SWAGGER_ENABLED}
    - MCP_ENABLED=${MCP_ENABLED}
    image: wushuo894/ani-rss:v3.2.9-arm32v7
    labels:
      createdBy: Apps
    networks:
      1panel-network:
        aliases:
        - ${CONTAINER_NAME}
    restart: always
    tty: true
    volumes:
    - ${CONFIG_PATH}:${CONFIG}
    - ${MEDIA_PATH}:/media

networks:
    1panel-network:
        external: true
services:
    handbrake:
        container_name: ${CONTAINER_NAME}
        deploy:
            resources:
                limits:
                    cpus: ${CPUS}
                    memory: ${MEMORY_LIMIT}
        volumes:
            - ${CONFIG_PATH}:/config
        environment:
            - PUID=99
            - PGID=100
            - TZ=${TIME_ZONE}
            - CUSTOM_USER=${CUSTOM_USER}
            - PASSWORD=${PASSWORD}
            - TITLE=${TITLE}
            - SELKIES_UI_TITLE=${SELKIES_UI_TITLE}
            - DASHBOARD=${DASHBOARD}
            - LC_ALL=${LC_ALL}
            - NVIDIA_VISIBLE_DEVICES=${NVIDIA_VISIBLE_DEVICES}
            - NVIDIA_DRIVER_CAPABILITIES=${NVIDIA_DRIVER_CAPABILITIES}
            - NVIDIA_ENABLE=${NVIDIA_ENABLE}
        # NVIDIA GPU 设备 cgroup 规则(主设备号 195),容器内可访问 /dev/nvidia*
        # 195 = nvidia0/ctl/uvm 等所有 NVIDIA 字符设备
        # NVIDIA_ENABLE=true 时配合 NVIDIA Container Toolkit 方可真正使用 GPU
        device_cgroup_rules:
            - 'c 195:* rw'
        image: linuxserver/handbrake:1.11.2
        labels:
            createdBy: Apps
        networks:
            - 1panel-network
        ports:
            - ${HOST_IP}:${PANEL_APP_PORT_HTTP}:3000
            - ${HOST_IP}:${PANEL_APP_PORT_HTTPS}:3001
        restart: always

